// ============================================================================
// Realtime intelligence helpers
// ----------------------------------------------------------------------------
// Pre-session augmentations that make the voice assistant materially
// smarter without architectural changes:
//
//   buildClinicalTrajectory — a one-paragraph synthesis of the patient's
//     trajectory, generated by gpt-4o-mini and cached per-patient for
//     10 min. Lets the voice model answer "where are we with her?" in
//     one turn instead of reading through five notes.
//
//   buildPatientVocabPrimer — comma-separated hint string for Whisper's
//     input_audio_transcription.prompt so unusual surnames and the
//     patient's specific medications/procedures get recognized reliably.
//
//   fetchRecentAiActions — recent audit rows touching this patient, so
//     the voice model has cross-session memory ("last time you added
//     LESI-3 to history, updated pharmacy, scheduled follow-up").
//
//   enrichNoteList — takes a note/procedure/report list and returns the
//     same entries with a short semantic hint per row, so matching a
//     voice phrase to a row is more robust than title-keyword only.
// ============================================================================

import OpenAI from 'openai';
import prisma, { isDatabaseHealthy } from '@/lib/db';
import type { ClinicalNoteView } from '@/lib/data/clinical-notes';
import type { PatientView } from '@/lib/data/patients';
import type { Session } from '@/lib/auth';
import { tenantScope } from '@/lib/tenancy';

// ---------------------------------------------------------------------------
// Clinical trajectory synthesis (#2 — richer context)
// ---------------------------------------------------------------------------

interface TrajectoryCacheEntry {
  summary: string;
  expires: number;
}

const trajectoryCache = new Map<string, TrajectoryCacheEntry>();
const TRAJECTORY_TTL_MS = 10 * 60 * 1000;
// Cap the cache so a long-running process with many patient visits
// doesn't grow unbounded. 500 entries × ~200 bytes each is trivial RAM
// but caps the blast radius of a memory leak. LRU-ish: when we breach
// the cap, drop the oldest-expiring quarter in one pass.
const TRAJECTORY_MAX_ENTRIES = 500;

function enforceCacheBound(): void {
  if (trajectoryCache.size <= TRAJECTORY_MAX_ENTRIES) return;
  const entries = Array.from(trajectoryCache.entries());
  entries.sort((a, b) => a[1].expires - b[1].expires);
  const dropCount = Math.ceil(TRAJECTORY_MAX_ENTRIES / 4);
  for (let i = 0; i < dropCount; i++) {
    const entry = entries[i];
    if (entry) trajectoryCache.delete(entry[0]);
  }
}

/**
 * One-paragraph synthesis of the patient's current clinical state.
 * Fast gpt-4o-mini call (~400ms) with a 10-min in-memory cache per
 * patient so re-opening the voice panel during the same clinic
 * session doesn't pay the cost twice.
 *
 * Returns '' on any failure — caller substitutes a safe fallback.
 */
export async function buildClinicalTrajectory(
  patient: PatientView,
  notes: ClinicalNoteView[],
  procedures: ClinicalNoteView[]
): Promise<string> {
  const cached = trajectoryCache.get(patient.id);
  if (cached && cached.expires > Date.now()) return cached.summary;

  if (notes.length === 0 && procedures.length === 0 && patient.briefHistory.length === 0) {
    return '';
  }

  const apiKey = process.env.OPENAI_API_KEY;
  if (!apiKey?.trim()) return '';

  // Cap input tokens — only need the last ~6 chronologically anchored
  // data points. Newer first in the source lists.
  const trajectorySource = [
    ...patient.briefHistory.slice(0, 8).map((h) => `[history] ${h}`),
    ...notes.slice(0, 4).map((n) =>
      `[note ${n.createdAt.slice(0, 10)}] ${n.title}: ${n.content.slice(0, 200)}`
    ),
    ...procedures.slice(0, 2).map((p) =>
      `[proc ${p.createdAt.slice(0, 10)}] ${p.title}`
    ),
  ].join('\n');

  try {
    const client = new OpenAI({ apiKey });
    const completion = await client.chat.completions.create({
      model: 'gpt-4o-mini',
      temperature: 0.2,
      max_tokens: 160,
      messages: [
        {
          role: 'system',
          content:
            'You synthesize a single plain-prose sentence (max 30 words) describing where a pain-management patient is in their treatment. Terse, factual, no hedging. Examples: "3rd LESI series started Feb; 60% relief, next follow-up pending." / "Post-op CESI 6 weeks ago, doing well, off opioids." If there is no data, return an empty string.',
        },
        { role: 'user', content: trajectorySource || '(no data)' },
      ],
    });
    const summary = (completion.choices[0]?.message?.content ?? '').trim();
    if (summary) {
      trajectoryCache.set(patient.id, {
        summary,
        expires: Date.now() + TRAJECTORY_TTL_MS,
      });
      enforceCacheBound();
    }
    return summary;
  } catch (err) {
    console.warn('[realtime/intelligence] trajectory synthesis failed:', err);
    return '';
  }
}

/** Bust the cache for a patient after any chart write. */
export function invalidateTrajectory(patientId: string): void {
  trajectoryCache.delete(patientId);
}

// ---------------------------------------------------------------------------
// Patient-specific vocabulary primer (#4)
// ---------------------------------------------------------------------------
// Hands Whisper a set of likely-appearing words so ethnic surnames,
// medication names, and procedure codes aren't mangled on every turn.
// Heuristic extraction — no LLM call, no latency cost.

const STOPWORDS = new Set([
  'the', 'and', 'for', 'with', 'from', 'this', 'that', 'have', 'has',
  'patient', 'today', 'follow', 'visit', 'note', 'doctor', 'clinic',
]);

function extractCandidates(text: string): string[] {
  const matches = text.match(/\b[A-Z][a-zA-Z0-9-]{2,}\b/g) ?? [];
  return matches.filter((w) => !STOPWORDS.has(w.toLowerCase()));
}

/**
 * Comma-separated hint string for Whisper. Caps at ~120 tokens of
 * content since OpenAI's docs warn long prompts can destabilize
 * transcription quality.
 */
export function buildPatientVocabPrimer(
  patient: PatientView,
  notes: ClinicalNoteView[],
  procedures: ClinicalNoteView[]
): string {
  const pool = new Set<string>();
  // Patient's own names + pharmacy name (unusual proper nouns).
  if (patient.firstName) pool.add(patient.firstName);
  if (patient.lastName) pool.add(patient.lastName);
  if (patient.pharmacyName) extractCandidates(patient.pharmacyName).forEach((w) => pool.add(w));
  if (patient.city) pool.add(patient.city);
  // History is short; pull capitalized terms (likely med/procedure names).
  for (const h of patient.briefHistory.slice(0, 10)) {
    extractCandidates(h).forEach((w) => pool.add(w));
  }
  // Note content — capitalized words only, bounded.
  for (const n of notes.slice(0, 5)) {
    extractCandidates(n.content.slice(0, 800)).forEach((w) => pool.add(w));
  }
  for (const p of procedures.slice(0, 3)) {
    extractCandidates(p.content.slice(0, 500)).forEach((w) => pool.add(w));
  }

  const words = Array.from(pool).slice(0, 50);
  if (words.length === 0) return '';
  return `Likely names and terms in this conversation: ${words.join(', ')}.`;
}

// ---------------------------------------------------------------------------
// Cross-visit memory (#5)
// ---------------------------------------------------------------------------
// Last ~8 audit rows where targetType=Patient/Document tied to this
// patient, formatted as short action phrases. Lets the voice model
// reference prior sessions without the doctor re-briefing.

const MEMORY_ACTIONS = new Set([
  'UPDATED_PATIENT',
  'CREATED_CLINICAL_NOTE',
  'EDITED_NOTE',
  'GENERATED_DRAFT_DOCUMENT',
  'SCHEDULED_VISIT',
  'UPDATED_APPOINTMENT_STATUS',
  'DELETED_APPOINTMENT',
  'CREATED_DOCUMENT',
  'DELETED_DOCUMENT',
]);

export async function fetchRecentAiActions(
  patientId: string,
  session: Session
): Promise<string[]> {
  if (!(await isDatabaseHealthy())) return [];
  try {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const rows: any[] = await prisma.auditLog.findMany({
      where: {
        ...tenantScope(session),
        success: true,
        // Actions touching this patient — either the patient is the
        // target directly, or the metadata's patientId field points to it.
        OR: [
          { targetId: patientId, targetType: 'Patient' },
          {
            targetType: 'Document',
            metadata: {
              path: ['patientId'],
              equals: patientId,
            },
          },
        ],
      },
      orderBy: { timestamp: 'desc' },
      take: 20,
      select: {
        action: true,
        timestamp: true,
        metadata: true,
      },
    });

    const kept = rows
      .filter((r) => MEMORY_ACTIONS.has(r.action))
      .slice(0, 8)
      .map((r) => {
        const when = new Date(r.timestamp).toISOString().slice(0, 10);
        const meta = (r.metadata ?? {}) as Record<string, unknown>;
        const via = meta.via === 'assistant' ? ' (via AI)' : '';
        const changed = Array.isArray(meta.changedFields)
          ? ` [${(meta.changedFields as string[]).slice(0, 4).join(', ')}]`
          : '';
        const category =
          typeof meta.category === 'string' ? ` (${meta.category})` : '';
        return `  ${when}: ${r.action}${category}${changed}${via}`;
      });
    return kept;
  } catch (err) {
    console.warn('[realtime/intelligence] audit memory query failed:', err);
    return [];
  }
}

// ---------------------------------------------------------------------------
// Enriched note/procedure/report lines (#3 — semantic matching)
// ---------------------------------------------------------------------------
// Each row gets a short content-derived hint so a phrase like "edit the
// back injection note" can match an LESI note whose title doesn't
// literally contain "back".

export function enrichNoteLine(n: ClinicalNoteView): string {
  const hint = inferHint(n);
  const hintPart = hint ? ` hint="${hint}"` : '';
  return `  id="${n.id}" title="${n.title}"${hintPart} created=${n.createdAt.split('T')[0]}`;
}

function inferHint(n: ClinicalNoteView): string {
  const blob = `${n.title} ${n.content}`.toLowerCase();
  const tags: string[] = [];
  // Spine / injection lexicon — common pain-management procedures.
  if (/\blesi\b|lumbar epidural|low back injection/.test(blob)) tags.push('lumbar epidural / back injection');
  if (/\bcesi\b|cervical epidural|neck injection/.test(blob)) tags.push('cervical epidural / neck injection');
  if (/\btesi\b|thoracic epidural/.test(blob)) tags.push('thoracic epidural');
  if (/medial branch|facet block|rfa|radiofrequency/.test(blob)) tags.push('facet / RFA');
  if (/si joint|sacroiliac/.test(blob)) tags.push('SI joint');
  if (/\bprp\b|platelet/.test(blob)) tags.push('PRP');
  if (/ketamine/.test(blob)) tags.push('ketamine');
  if (/opioid|norco|oxycodone|hydrocodone|percocet|tramadol/.test(blob)) tags.push('opioid rx');
  if (/mri|ct scan|x-ray|imaging/.test(blob)) tags.push('imaging');
  if (/pt\b|physical therapy/.test(blob)) tags.push('PT');
  if (/consult|referr|intake/.test(blob)) tags.push('consult / referral');
  if (/follow.?up|f\/u/.test(blob)) tags.push('follow-up');
  // Body region.
  if (/low back|lumbar/.test(blob)) tags.push('low back');
  if (/neck|cervical/.test(blob)) tags.push('neck');
  if (/knee/.test(blob)) tags.push('knee');
  if (/shoulder/.test(blob)) tags.push('shoulder');
  if (/headache|migraine|occipital/.test(blob)) tags.push('head');

  // De-dupe, cap.
  return Array.from(new Set(tags)).slice(0, 4).join(' · ');
}
